    const s = world.state;
    if (s.wanted > 0) {
      s.wantedHeat = Math.max(0, s.wantedHeat - WANTED.decay * dt);
      s.wanted = Math.ceil(s.wantedHeat);
    }
    sirenTimer -= dt;
    if (s.wanted > 0 && sirenTimer <= 0) { sirenTimer = 1.4; if (audio) audio.siren(); }
